<?php require __DIR__.'/config.php'; require_login(); $stmt=$db->prepare('SELECT email FROM users WHERE id=?'); $stmt->execute([$_SESSION['user_id']]); $user=$stmt->fetch(PDO::FETCH_ASSOC); $db->prepare('UPDATE users SET last_login_at=? WHERE id=?')->execute([gmdate('c'),$_SESSION['user_id']]); page('<h1>Angemeldet</h1><p>'.h($user['email']).'</p><p><a href="logout.php">Abmelden</a></p>'); ?>